// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize(); // test contract becomes the owner; never prank, so msg.sender stays the owner
    }

    function testFuzz_property(address newOwner, address other) public {
        // admissible domain: newOwner is a real, nonzero address that is NOT the caller (owner)
        vm.assume(newOwner != address(0));
        vm.assume(other != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(newOwner != other);

        // boundary call from the owner (default caller is this contract = owner)
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful transfer to newOwner makes newOwner the owner.
        assertTrue(ok && c.owner() == newOwner);
    }
}
